using Crown.Core;
using System.Text.Json.Nodes;

internal static class StageTwentyNineSpecs
{
    private static void Assert(bool ok,string message){if(!ok)throw new Exception(message);}
    private static GameState Fresh(){var s=World.Create();Narrative.Resolve(s,0);return s;}
    private static void Phases(GameState s,int count,bool ready=true)
    {
        var c=s.Cities[0];for(int i=0;i<count;i++){c.Food=ready?100:0;c.HungerTurns=ready?0:1;LocalCouncils.Tick(s);s.Turn++;}
    }
    public static void Run(Action<string,Action> test)
    {
        test("Large late-campaign populations retain valid scaled council fees",()=>{var s=Fresh();s.Player.Gold=10000;var c=s.Cities[0];c.Population=900;Assert(LocalCouncils.Begin(s,c.Id,LocalMandate.Granaries).Success&&c.Council.PhaseFee==303,"Population scaling failed");Assert(SaveGame.Deserialize(SaveGame.Serialize(s)).Cities[0].Council.PhaseFee==303,"A valid large-city agreement cannot reload");});
        test("Era acceleration keeps years advancing and forecasts do not add ancient centuries",()=>{var s=Fresh();s.Turn=2;s.Player.Technologies.UnionWith(EpochCatalog.All.Take(6).SelectMany(e=>e.Technologies));CampaignCalendar.Remember(s);int year=s.Year;Assert(CampaignCalendar.At(s,8)=="ok. "+CampaignCalendar.Format(year+6),"Forecast added the ancient calendar stride to a medieval year");s.Turn++;CampaignCalendar.Remember(s);Assert(s.Year==year+1,"Accelerated history froze the calendar");});
        test("AI provincial councils require the player channel and pay from their own treasury",()=>{var s=Fresh();var c=s.Cities.First(c=>c.Owner==1);c.Food=100;s.Factions[1].Gold=1000;s.Turn=16+c.Id%16;LocalCouncils.Tick(s);Assert(!c.Council.Established,"Unintroduced AI channel opened");s.Cities[0].Council.Established=true;double player=s.Player.Gold;LocalCouncils.Tick(s);Assert(c.Council.Established&&c.Council.Phases==1&&s.Factions[1].Gold==970-c.Council.PhaseFee&&s.Player.Gold==player,"AI council charged wrong treasury or skipped conditions");});
        test("V26 migration retains exact predecessor bytes and replaces old abbreviated history",()=>{var s=Fresh();s.Turn=8;s.Chronicle.Add(new(){Turn=1,Text="Decyzja T1; raport T5.",Category="decyzja"});var j=JsonNode.Parse(SaveGame.Serialize(s))!;j["Version"]=26;j.AsObject().Remove("CalendarYears");foreach(var c in j["Cities"]!.AsArray())c!.AsObject().Remove("Council");string raw=j.ToJsonString();string path=Path.Combine(Path.GetTempPath(),"crown-v26-"+Guid.NewGuid()+".crown");try{File.WriteAllText(path,raw);var loaded=SaveGame.Read(path);Assert(loaded.Version==27&&loaded.Cities.All(c=>!c.Council.Established)&&loaded.Chronicle.Last().Text.Contains("ok.")&&!loaded.Chronicle.Last().Text.Contains("T1"),"Migration invented politics or retained a turn code");SaveGame.Write(loaded,path);Assert(File.ReadAllText(path+".v26.bak")==raw,"Predecessor backup differs");}finally{if(File.Exists(path))File.Delete(path);if(File.Exists(path+".v26.bak"))File.Delete(path+".v26.bak");}});
        test("A calendar cannot rewrite an earlier phase to be later than its successor",()=>{var s=Fresh();s.Turn=3;s.CalendarYears[1]=2000;s.CalendarYears[2]=1900;bool rejected=false;try{SaveGame.Deserialize(SaveGame.Serialize(s));}catch(InvalidDataException){rejected=true;}Assert(rejected,"Backward calendar accepted");});
        test("Captured years survive later eras and save round trips",()=>{var s=Fresh();int year=s.Year;s.Log("Decyzja A","decyzja");s.Turn++;s.Player.Technologies.UnionWith(EpochCatalog.All.SelectMany(e=>e.Technologies));s.Log("Decyzja B","decyzja");var copy=SaveGame.Deserialize(SaveGame.Serialize(s));Assert(copy.CalendarYears[1]==year&&CampaignCalendar.At(copy,1)==CampaignCalendar.Format(year)&&copy.Year>=year,"History was redated");});
        test("Future dates are explicitly estimated and do not mutate the campaign",()=>{var s=Fresh();string before=SaveGame.Serialize(s);Assert(CampaignCalendar.At(s,13).StartsWith("ok. ")&&CampaignCalendar.At(s,null)=="brak daty","Missing estimate marker");Assert(SaveGame.Serialize(s)==before,"Calendar preview mutated state");});
        test("Old histories retain uncertainty instead of invented exact dates",()=>{var s=Fresh();s.Turn=8;var json=JsonNode.Parse(SaveGame.Serialize(s))!;json["Version"]=26;json.AsObject().Remove("CalendarYears");var old=SaveGame.Deserialize(json.ToJsonString());Assert(CampaignCalendar.At(old,1).StartsWith("ok. ")&&!CampaignCalendar.At(old,8).StartsWith("ok. "),"Old chronology presented as exact");});
        test("Legacy campaign retains its original calendar",()=>{var s=World.CreateLegacy();s.Turn=10;Assert(s.Year==-2265&&CampaignCalendar.At(s,12).StartsWith("ok. "),"Legacy dates changed");});
        test("Invalid calendars cannot enter a current save",()=>{var s=Fresh();s.CalendarYears[0]=1900;bool rejected=false;try{SaveGame.Deserialize(SaveGame.Serialize(s));}catch(InvalidDataException){rejected=true;}Assert(rejected,"Invalid calendar accepted");});
        test("Reading and saving an undated current phase preserve exact state",()=>{var s=Fresh();s.Turn=7;string before=SaveGame.Serialize(s);Assert(SaveGame.Serialize(SaveGame.Deserialize(before))==before,"Load fabricated a timestamp");});
        test("Local preview and rejected agreement do not spend money or change politics",()=>{var s=Fresh();var c=s.Cities[0];s.Player.Gold=0;string before=SaveGame.Serialize(s);Assert(LocalCouncils.Error(s,c,LocalMandate.Granaries)!=null&&!LocalCouncils.Begin(s,c.Id,LocalMandate.Granaries).Success,"Unaffordable mandate accepted");Assert(SaveGame.Serialize(s)==before,"Rejected mandate mutated state");});
        test("Signing a local coalition pays exactly once and shifts competing support",()=>{var s=Fresh();var c=s.Cities[0];double gold=s.Player.Gold;Assert(LocalCouncils.Begin(s,c.Id,LocalMandate.Granaries).Success,"Signing failed");Assert(s.Player.Gold==gold-30&&c.Council.Families==58&&c.Council.Landholders==45,"Wrong coalition cost");Assert(!LocalCouncils.Begin(s,c.Id,LocalMandate.Crafts).Success&&s.Player.Gold==gold-30,"Duplicate signature charged");});
        test("Delivered food agreement establishes a permanent economic charter",()=>{var s=Fresh();s.Player.Gold=1000;var c=s.Cities[0];LocalCouncils.Begin(s,c.Id,LocalMandate.Granaries);int fee=c.Council.PhaseFee;Phases(s,6);Assert(c.Council.Charters.Contains(LocalMandate.Granaries)&&c.Council.Mandate==LocalMandate.None&&c.Council.Delivered==6&&s.Player.Gold==970-fee*6&&LocalCouncils.Bonus(c).Food==2,"Wrong delivery or economics");SaveGame.Deserialize(SaveGame.Serialize(s));});
        test("Four real deliveries suffice while failed phases are never charged",()=>{var s=Fresh();s.Player.Gold=1000;var c=s.Cities[0];LocalCouncils.Begin(s,c.Id,LocalMandate.Granaries);Phases(s,2,false);Phases(s,4);Assert(c.Council.Charters.Count==1&&c.Council.Delivered==4&&c.Council.Paid==4*c.Council.PhaseFee,"Non-deliveries were counted");});
        test("Unfunded promises fail with political consequences and no free charter",()=>{var s=Fresh();var c=s.Cities[0];LocalCouncils.Begin(s,c.Id,LocalMandate.Granaries);s.Player.Gold=0;int loyalty=c.Loyalty;Phases(s,6);Assert(c.Council.Charters.Count==0&&c.Council.Delivered==0&&c.Council.Families==40&&c.Unrest==8&&c.Loyalty==loyalty-8,"Failed pledge escaped consequences");});
        test("Paused workshops cannot fulfil a craft agreement",()=>{var s=Fresh();s.Player.Gold=1000;var c=s.Cities[0];c.Buildings.Add("workshop");c.ProductionPaused=true;LocalCouncils.Begin(s,c.Id,LocalMandate.Crafts);Phases(s,6);Assert(c.Council.Delivered==0&&c.Council.Charters.Count==0,"Paused craft factory counted");});
        test("Missing or suspended schools cannot fulfil an education promise",()=>{foreach(bool suspended in new[]{false,true}){var s=Fresh();s.Player.Gold=1000;var c=s.Cities[0];if(suspended){c.Buildings.Add("library");c.SuspendedBuildings.Add("library");}LocalCouncils.Begin(s,c.Id,LocalMandate.Schools);Phases(s,6);Assert(c.Council.Delivered==0,"Inactive school counted");}});
        test("School and craft charters provide different permanent yields",()=>{foreach(var m in new[]{LocalMandate.Crafts,LocalMandate.Schools}){var s=Fresh();s.Player.Gold=1000;var c=s.Cities[0];c.Buildings.Add(m==LocalMandate.Crafts?"workshop":"library");c.ProductionPaused=false;LocalCouncils.Begin(s,c.Id,m);Phases(s,6);var y=LocalCouncils.Bonus(c);Assert(c.Council.Charters.Contains(m)&&(m==LocalMandate.Crafts?y.Production==2:y.Science==2),"Missing distinct charter");}});
        test("A mandate uses a fixed fee and settles each phase at most once",()=>{var s=Fresh();s.Player.Gold=1000;var c=s.Cities[0];LocalCouncils.Begin(s,c.Id,LocalMandate.Granaries);int fee=c.Council.PhaseFee;c.Population=30;c.Food=100;LocalCouncils.Tick(s);double gold=s.Player.Gold;LocalCouncils.Tick(s);Assert(c.Council.Phases==1&&c.Council.PhaseFee==fee&&s.Player.Gold==gold,"Duplicate or repriced phase");});
        test("Current local agreements resume deterministically after reload",()=>{var a=Fresh();a.Player.Gold=1000;LocalCouncils.Begin(a,a.Cities[0].Id,LocalMandate.Granaries);Phases(a,3);var b=SaveGame.Deserialize(SaveGame.Serialize(a));Phases(a,3);Phases(b,3);Assert(SaveGame.Serialize(a)==SaveGame.Serialize(b),"Local outcomes diverged after reload");});
        test("Ownership changes dissolve promises and charters without charging the conqueror",()=>{var s=Fresh();var c=s.Cities[0];LocalCouncils.Begin(s,c.Id,LocalMandate.Granaries);c.Council.Charters.Add(LocalMandate.Schools);double gold=s.Factions[1].Gold;ProvincialPolitics.Transfer(s,c,1);Assert(!c.Council.Established&&c.Council.Mandate==LocalMandate.None&&c.Council.Charters.Count==0&&s.Factions[1].Gold==gold,"Political debt crossed sovereignty");});
        test("Local charters cannot be farmed by signing the same agreement repeatedly",()=>{var s=Fresh();s.Player.Gold=1000;var c=s.Cities[0];LocalCouncils.Begin(s,c.Id,LocalMandate.Granaries);Phases(s,6);s.Turn=20;Assert(!LocalCouncils.Begin(s,c.Id,LocalMandate.Granaries).Success,"Repeated charter accepted");});
        test("Foreign cities and pending narrative choices block player signatures",()=>{var s=Fresh();Assert(!LocalCouncils.Begin(s,s.Cities.First(c=>c.Owner==1).Id,LocalMandate.Crafts).Success,"Foreign council controlled");s.PendingEvent="founding";Assert(!LocalCouncils.Begin(s,s.Cities[0].Id,LocalMandate.Granaries).Success,"Unresolved narrative bypassed");});
        test("Malformed payment evidence and impossible local supports are rejected",()=>{foreach(string field in new[]{"Paid","Families","Phases","Delivered"}){var s=Fresh();LocalCouncils.Begin(s,s.Cities[0].Id,LocalMandate.Granaries);var j=JsonNode.Parse(SaveGame.Serialize(s))!;j["Cities"]![0]!["Council"]![field]=999;bool rejected=false;try{SaveGame.Deserialize(j.ToJsonString());}catch(InvalidDataException){rejected=true;}Assert(rejected,"Forged "+field+" accepted");}});
        test("A real economic turn delivers a food pledge and keeps a valid save",()=>{var s=Fresh();s.Player.Gold=1000;var c=s.Cities[0];c.Food=500;LocalCouncils.Begin(s,c.Id,LocalMandate.Granaries);Assert(Engine.EndTurn(s).Success&&c.Council.Phases==1&&c.Council.Delivered==1,"Ordinary turn did not execute council");SaveGame.Deserialize(SaveGame.Serialize(s));});
    }
}
